// include common definitions (defines DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "mvt.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Array initialization translated to Halide.
 *
 * Original C:
 *   for (i = 0; i < n; i++) {
 *     x1[i]  = (DATA_TYPE) (i % n) / n;
 *     x2[i]  = (DATA_TYPE) ((i + 1) % n) / n;
 *     y_1[i] = (DATA_TYPE) ((i + 3) % n) / n;
 *     y_2[i] = (DATA_TYPE) ((i + 4) % n) / n;
 *     for (j = 0; j < n; j++)
 *       A[i][j] = (DATA_TYPE) (i*j % n) / n;
 *   }
 */
static
void init_array(int n,
                Halide::Buffer<num_t, 1> x1,
                Halide::Buffer<num_t, 1> x2,
                Halide::Buffer<num_t, 1> y_1,
                Halide::Buffer<num_t, 1> y_2,
                Halide::Buffer<num_t, 2> A) {
    Var i("i"), j("j");

    Func init_x1("init_x1");
    Func init_x2("init_x2");
    Func init_y1("init_y1");
    Func init_y2("init_y2");
    Func init_A("init_A");

    // 1D vectors
    init_x1(i) = cast<num_t>(i % n) / cast<int>(n);
    init_x2(i) = cast<num_t>((i + 1) % n) / cast<int>(n);
    init_y1(i) = cast<num_t>((i + 3) % n) / cast<int>(n);
    init_y2(i) = cast<num_t>((i + 4) % n) / cast<int>(n);

    // 2D matrix A: C layout A[i][j] is stored as A(j, i) so that
    // the j-dimension (columns) is contiguous in memory.
    init_A(j, i) = cast<num_t>((i * j) % n) / cast<int>(n);

    // Realize into the provided buffers
    init_x1.realize(x1);
    init_x2.realize(x2);
    init_y1.realize(y_1);
    init_y2.realize(y_2);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to:
    //   DATA_TYPE A[N][N];
    //   DATA_TYPE x1[N], x2[N], y_1[N], y_2[N];
    //
    // PolyBench uses A[i][j]; we map j -> dim 0 (x), i -> dim 1 (y).
    Halide::Buffer<num_t, 2> A(n, n);     // (j, i)
    Halide::Buffer<num_t, 1> x1(n);
    Halide::Buffer<num_t, 1> x2(n);
    Halide::Buffer<num_t, 1> y_1(n);
    Halide::Buffer<num_t, 1> y_2(n);

    // ImageParams to feed into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x1_param(type_of<num_t>(), 1, "x1_param");
    ImageParam x2_param(type_of<num_t>(), 1, "x2_param");
    ImageParam y1_param(type_of<num_t>(), 1, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 1, "y2_param");

    // Initialize data using a Halide-based initializer
    init_array(n, x1, x2, y_1, y_2, A);

    // Bind buffers to ImageParams
    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y_1);
    y2_param.set(y_2);

    // ------------------------------------------------------------------
    // Halide translation of kernel_mvt:
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // Mathematically:
    //   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    //   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    //
    // With our (j, i) mapping for A[i][j]:
    //   A[i][j]  -> A_param(j, i)
    //   A[j][i]  -> A_param(i, j)
    // ------------------------------------------------------------------

    Var i("i");
    // Use the width of A (dim 0, corresponding to j) as the reduction extent.
    // This is constant for this run, but passed as an Expr to Halide.
    RDom r(0, A.dim(0).extent(), "r");

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // First loop nest: accumulate into x1
    // x1[i] = x1[i] + sum_r A_param(r, i) * y1_param(r);
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(r, i) * y1_param(r);

    // Second loop nest: accumulate into x2
    // x2[i] = x2[i] + sum_r A_param(i, r) * y2_param(r);
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // ------------------------ Scheduling ------------------------------
    // We target a modern CPU: parallelize across i (independent rows)
    // and vectorize the inner reductions for good cache and SIMD usage.
    Target target = get_jit_target_from_environment();
    Type num_type = type_of<num_t>();
    int vec_width = target.natural_vector_size(num_type);
    if (vec_width < 1) {
        vec_width = 1;
    }

    // --- Schedule for mvt_x1 -----------------------------------------
    // Access pattern:
    //   mvt_x1 update uses A_param(r, i) with r along dim 0 (contiguous),
    //   so we want r in the innermost loop and vectorize across r.
    mvt_x1.compute_root();

    // Parallelize across i for both the pure and update definitions
    mvt_x1.parallel(i);

    // Split the reduction domain r into [r_outer, r_inner] and
    // vectorize across r_inner (contiguous loads along A_param dim 0).
    {
        RVar r_outer_x1("r_outer_x1"), r_inner_x1("r_inner_x1");
        mvt_x1
            .update()
            .split(r, r_outer_x1, r_inner_x1, vec_width)
            .vectorize(r_inner_x1)
            .parallel(i);  // each i is independent
    }

    // --- Schedule for mvt_x2 -----------------------------------------
    // Access pattern:
    //   mvt_x2 update uses A_param(i, r). With the default i-outer, r-inner
    //   order this walks A down the column (strided). To improve locality,
    //   we reorder the reduction to run over r in the outer loop and i in
    //   the inner loop:
    //
    //   for r:
    //     for i:
    //       x2[i] += A_param(i, r) * y2[r];
    //
    // Now for a fixed r we walk A_param(:, r) with contiguous i.
    mvt_x2.compute_root();

    // Parallelize across i for the pure definition (initial copy from x2).
    mvt_x2.parallel(i);

    {
        Var i_outer_x2("i_outer_x2"), i_inner_x2("i_inner_x2");

        // For the update:
        //   - Split i so that we can vectorize across i_inner_x2.
        //   - Reorder so that the final loop nest is:
        //       for r
        //         for i_outer_x2 (parallel)
        //           for i_inner_x2 (vectorized)
        mvt_x2
            .update()
            .split(i, i_outer_x2, i_inner_x2, vec_width)
            .reorder(i_inner_x2, i_outer_x2, r)  // inner -> outer
            .vectorize(i_inner_x2)
            .parallel(i_outer_x2);
    }

    // ------------------------------------------------------------------
    // JIT-compile the two Funcs with the chosen target
    mvt_x1.compile_jit(target);
    mvt_x2.compile_jit(target);

    // Time the kernel execution (both x1 and x2 updates)
    auto start = std::chrono::high_resolution_clock::now();

    // Realize back into x1 and x2 buffers (in-place relative to the C view)
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results to stderr (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print x1
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x1(idx) << '\n';
        }
        // Print x2
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x2(idx) << '\n';
        }
    }

    // Print timing (seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
