    // inner/contiguous dimension. The exact vector width is not
    // critical here; 8 is a reasonable fixed choice for modern x64
    // CPUs (it maps well to AVX2 for float, SSE for double, etc.), and
    // Halide will handle tails correctly.
    const int vec = 8;

    init_x1
        .compute_root()
        .parallel(i)
        .vectorize(i, vec);

    init_x2
        .compute_root()
        .parallel(i)
        .vectorize(i, vec);

    init_y1
        .compute_root()
        .parallel(i)
        .vectorize(i, vec);

    init_y2
        .compute_root()
        .parallel(i)
        .vectorize(i, vec);

