    // Scheduling for performance
    // ------------------------------------------------------------------
    //
    // Key goals:
    //   - Good data locality for A and y_1 / y_2 accesses.
    //   - Parallelize across i (rows / columns) where safe.
    //   - Vectorize where it is straightforward and safe.
    //
    // Notes:
    //   - For mvt_x1:
    //       A is accessed as A_param(r, i) with r varying and i fixed.
    //       r corresponds to j and is dim 0 (contiguous). The default
    //       reduction loop order (i outer, r inner) already gives
    //       unit-stride access over r. We parallelize across i and
    //       leave vectorization decisions to Halide's internal
    //       heuristics for this simple reduction (we avoid vectorizing
    //       the reduction variable explicitly to keep the schedule
    //       simple and obviously correct).
    //
    //   - For mvt_x2:
    //       A is accessed as A_param(i, r). Here i is dim 0 (contiguous),
    //       r is dim 1. To get contiguous access to A, we want i to
    //       vary in the innermost loop. We also want to parallelize
    //       and vectorize across i. We achieve this by splitting i
    //       into tiles (i_outer, i_inner), vectorizing i_inner, and
    //       reordering the update loops so that the order becomes:
    //           for r (reduction over j)
    //             for i_outer (tiles of i)  [parallel]
    //               for i_inner (within a tile) [vectorized]
    //
    //       This preserves the mathematical meaning because the
    //       accumulation is associative and we never parallelize over
    //       the reduction variable r.
    //

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    const int i_tile = 64; // tile size in i for parallelism + cache locality

    // ---- Schedule mvt_x1 ----
    {
        // Compute x1 at the root; parallelize across i (each output x1[i]
        // is an independent reduction over r).
        mvt_x1.compute_root()
              .parallel(i);
        // The update step inherits the same loop nest around i; we
        // don't add extra directives here to keep it simple and to
        // maintain the favorable "i-outer, r-inner" order for A(r,i).
    }

    // ---- Schedule mvt_x2 ----
    {
        Var i_outer("i_outer"), i_inner("i_inner");

        // Pure definition: simple per-element copy from x2_param,
        // tiled and vectorized over i.
        mvt_x2.compute_root()
              .split(i, i_outer, i_inner, i_tile)
              .parallel(i_outer)
              .vectorize(i_inner, vec_width);

        // Update definition (the reduction):
        //   Original logical loops (without scheduling) are:
        //     for i:       // pure var
        //       for r:     // reduction var
        //         x2[i] += A(i, r) * y2[r];
        //
        //   After split(i, i_outer, i_inner, i_tile) we have loop vars:
        //     i_outer, i_inner, r
        //
        //   We reorder to make i_inner innermost (for vectorization and
        //   contiguous access to A and x2) and r outer to preserve the
        //   reduction structure:
        //     for r:
        //       for i_outer (parallel):
        //         for i_inner (vectorized):
        //           x2[i_outer * i_tile + i_inner] += ...
        //
        mvt_x2.update()
              .split(i, i_outer, i_inner, i_tile)
              // reorder arguments from innermost to outermost:
              //   innermost:   i_inner  (vectorized)
              //   middle:      i_outer  (parallel)
              //   outermost:   r        (reduction over j)
              .reorder(i_inner, i_outer, r)
              .parallel(i_outer)
              .vectorize(i_inner, vec_width);
    }

    // JIT-compile the two Funcs with the chosen target
    mvt_x1.compile_jit(target);
    mvt_x2.compile_jit(target);

    // Time the kernel execution (both x1 and x2 updates)
    auto start = std::chrono::high_resolution_clock::now();

    // Realize back into x1 and x2 buffers (in-place relative to the C view)
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results to stderr (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print x1
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x1(idx) << '\n';
        }
        // Print x2
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x2(idx) << '\n';
        }
    }

    // Print timing (seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
