    Func init_x2("init_x2");
    Func init_y1("init_y1");
    Func init_y2("init_y2");
    Func init_A("init_A");

    // Precompute 1/n once as num_t to avoid repeated division by int.
    Expr inv_n = cast<num_t>(1.0) / cast<num_t>(n);

    // 1D vectors
    init_x1(i) = cast<num_t>(i % n) * inv_n;
    init_x2(i) = cast<num_t>((i + 1) % n) * inv_n;
    init_y1(i) = cast<num_t>((i + 3) % n) * inv_n;
    init_y2(i) = cast<num_t>((i + 4) % n) * inv_n;

    // 2D matrix A: C layout A[i][j] -> Halide A(j, i) to keep j contiguous
    init_A(j, i) = cast<num_t>((i * j) % n) * inv_n;

    // -----------------
    // Scheduling (CPU)
    // -----------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Vector inits: simple 1D, parallelized across i.
    init_x1.compute_root()
           .parallel(i)
           .vectorize(i, vec_width);
    init_x2.compute_root()
           .parallel(i)
           .vectorize(i, vec_width);
    init_y1.compute_root()
           .parallel(i)
           .vectorize(i, vec_width);
    init_y2.compute_root()
           .parallel(i)
           .vectorize(i, vec_width);

    // Matrix init: parallel over rows (i), SIMD over contiguous j.
    init_A.compute_root()
          .parallel(i)
          .vectorize(j, vec_width);

    // Realize into the provided buffers
    init_x1.realize(x1);
    init_x2.realize(x2);
    init_y1.realize(y_1);
    init_y2.realize(y_2);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

