    // PolyBench uses A[i][j]; we map j -> dim 0 (x), i -> dim 1 (y) so that
    // the inner j-loop is contiguous in memory.
    Halide::Buffer<num_t, 2> A(n, n);     // (j, i)
    Halide::Buffer<num_t, 1> x1(n);
    Halide::Buffer<num_t, 1> x2(n);
    Halide::Buffer<num_t, 1> y_1(n);
    Halide::Buffer<num_t, 1> y_2(n);

    // ImageParams to feed into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x1_param(type_of<num_t>(), 1, "x1_param");
    ImageParam x2_param(type_of<num_t>(), 1, "x2_param");
    ImageParam y1_param(type_of<num_t>(), 1, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 1, "y2_param");

    // Initialize data using a Halide-based initializer
    init_array(n, x1, x2, y_1, y_2, A);

    // Bind buffers to ImageParams
    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y_1);
    y2_param.set(y_2);

    // Halide translation of kernel_mvt:
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // Mathematically:
    //   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    //   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    //
    // With our (j, i) mapping for A[i][j]:
    //   A[i][j]  -> A_param(j, i)
    //   A[j][i]  -> A_param(i, j)

    Var i("i");
    // Use the width of A (dim 0, corresponding to j) as the reduction extent.
    RDom r(0, A.dim(0).extent(), "r");

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // First loop nest: accumulate into x1
    // x1[i] += sum_j A[i][j] * y_1[j]
    // -> x1_param(i) + sum_r A_param(r, i) * y1_param(r)
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(r, i) * y1_param(r);

    // Second loop nest: accumulate into x2
    // x2[i] += sum_j A[j][i] * y_2[j]
    // -> x2_param(i) + sum_r A_param(i, r) * y2_param(r)
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // -----------------
    // Scheduling (CPU)
    // -----------------
    //
    // Strategy:
    //   - Compute each gemv result at the root.
    //   - Parallelize across i (rows / columns): each i is independent.
    //   - Keep the reduction variable r innermost so that:
    //       * mvt_x1: A_param(r, i) walks contiguous memory in r (good locality)
    //       * mvt_x2: A_param(i, r) is strided; we can't fix that without
    //         transposing or fusing kernels, but at least we exploit parallelism.
    //
    // By default, Halide uses all pure Vars outside of reduction Vars
    // and all RVars innermost, which gives i-outer, r-inner for these
    // one-dimensional reductions. That matches the original C code and
    // is cache-friendly for mvt_x1.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // For this kernel, the main gain comes from multi-core parallelism.
    // We keep the schedule simple and robust: parallelize across i for both
    // the initialization (pure step) and the reduction (update step).
    //
    // We do not aggressively vectorize the reduction loops here because:
    //   - The reduction is over r, and vectorizing over i is best done with
    //     a split-and-parallel strategy; that adds complexity for modest gain.
    //   - Compilers will still auto-vectorize the inner r-loop where possible.
    //
