    init_A(j, i) = cast<num_t>((i * j) % n) / cast<int>(n);

    // --- Initialization schedule ---
    //
    // All of these are embarrassingly parallel. We:
    //  - parallelize over i (rows)
    //  - vectorize over the innermost dimension where sensible
    //
    // A fixed vector width of 8 is a reasonable choice on modern x86
    // (e.g. AVX, AVX2). Halide will generate appropriate tail code
    // when n is not a multiple of 8.
    const int vec = 8;

    init_x1
        .compute_root()
        .parallel(i)
        .vectorize(i, vec);

    init_x2
        .compute_root()
        .parallel(i)
        .vectorize(i, vec);

    init_y1
        .compute_root()
        .parallel(i)
        .vectorize(i, vec);

    init_y2
        .compute_root()
        .parallel(i)
        .vectorize(i, vec);

    // For A(j, i): i (second var) is outer, j (first var) is inner by
    // default, which matches our desire: j is contiguous in memory.
    init_A
        .compute_root()
        .parallel(i)      // parallel over rows (original i index)
        .vectorize(j, vec); // vectorize across contiguous j

    // Realize into the provided buffers
    init_x1.realize(x1);
    init_x2.realize(x2);
    init_y1.realize(y_1);
    init_y2.realize(y_2);
    init_A.realize(A);
}

